steps.run:
set -euo pipefail
case "${{ github.event_name }}" in
  pull_request) MODE=pull_request ;;
  push) MODE=push ;;
  schedule) MODE=schedule ;;
  workflow_dispatch) MODE=dispatch ;;
  merge_group) MODE=merge_group ;;
  *) echo "REZHIM: ${{ github.event_name }}" >&2; exit 1 ;;
esac
ARGS=(--mode "$MODE" --out selection.json --repo .)
if [ "$MODE" = pull_request ]; then
  ARGS+=(--base-sha "${{ github.event.pull_request.base.sha }}" --head-sha "${{ github.event.pull_request.head.sha }}" --pr "${{ github.event.pull_request.number }}")
elif [ "$MODE" = push ]; then
  ARGS+=(--base-sha "${{ github.event.before }}" --head-sha "${{ github.sha }}")
elif [ "$MODE" = merge_group ]; then
  ARGS+=(--base-sha "${{ github.event.merge_group.base_sha }}" --head-sha "${{ github.event.merge_group.head_sha }}")
fi
node mobile/scripts/select-ci-screens.cjs "${ARGS[@]}"
{
  echo "selection<<SELECTION_KONEC"
  cat selection.json
  echo "SELECTION_KONEC"
} >> "$GITHUB_OUTPUT"

set -euo pipefail
node -e '
  const fs = require("fs");
  const sel = JSON.parse(fs.readFileSync("selection.json", "utf8"));
  const fs2 = require("fs");
  const out = [];
  for (const s of sel.selected) out.push(`${s.job}=true`);
  for (const e of sel.excluded) out.push(`${e.job}=false`);
  fs2.appendFileSync(process.env.GITHUB_OUTPUT, out.join("\n") + "\n");
'

set -e
mkdir -p /tmp/dev-harness-verify
cp -a . /tmp/dev-harness-verify/impl995-r-${{ github.run_id }}-${{ github.run_attempt }}
python3 -m pip install -r /tmp/dev-harness-verify/impl995-r-${{ github.run_id }}-${{ github.run_attempt }}/.harness/fixtures/workshop_project/pilot_995/requirements.txt
cd /tmp/dev-harness-verify/impl995-r-${{ github.run_id }}-${{ github.run_attempt }}
python3 .harness/fixtures/workshop_project/pilot_995/probe.py --repo . --check-frozen

set -e
mkdir -p /tmp/dev-harness-verify
cp -a . /tmp/dev-harness-verify/impl108-r-${{ github.run_id }}-${{ github.run_attempt }}
cd /tmp/dev-harness-verify/impl108-r-${{ github.run_id }}-${{ github.run_attempt }}
python3 .harness/fixtures/workshop_project/start_108/start_static_probe.py --repo .
python3 .harness/fixtures/workshop_project/start_108/start_probe.py --repo .

set -e
mkdir -p /tmp/dev-harness-verify
cp -a . /tmp/dev-harness-verify/impl111-r-${{ github.run_id }}-${{ github.run_attempt }}
cd /tmp/dev-harness-verify/impl111-r-${{ github.run_id }}-${{ github.run_attempt }}
python3 .harness/fixtures/workshop_project/first_run_111/first_run_static_probe.py --repo .
python3 .harness/fixtures/workshop_project/first_run_111/first_run_probe.py --repo .

set -e
mkdir -p /tmp/dev-harness-verify
node mobile/scripts/select-ci-screens.cjs --mode inventar --repo . \
  --out /tmp/dev-harness-verify/impl-inventar-${{ github.run_id }}-${{ github.run_attempt }}.json \
  > /tmp/dev-harness-verify/impl-inventar-${{ github.run_id }}-${{ github.run_attempt }}.out
while IFS= read -r stroka; do
  case "$stroka" in
    PACHKA\ *)
      pachka="${stroka#PACHKA }"
      test -n "$pachka"
      test -d "$pachka"
      mv "$pachka" "/tmp/dev-harness-verify/impl-pack-$(basename "${pachka%/}")-${{ github.run_id }}-${{ github.run_attempt }}"
      ;;
  esac
done < /tmp/dev-harness-verify/impl-inventar-${{ github.run_id }}-${{ github.run_attempt }}.out
mv .harness /tmp/dev-harness-verify/impl995-h-${{ github.run_id }}-${{ github.run_attempt }}
mv .harness117 /tmp/dev-harness-verify/impl117-b-${{ github.run_id }}-${{ github.run_attempt }}
mv .harness117b /tmp/dev-harness-verify/impl117b-b-${{ github.run_id }}-${{ github.run_attempt }}
mv .harness151 /tmp/dev-harness-verify/impl151-h-${{ github.run_id }}-${{ github.run_attempt }}
mv mobile/src/bootstrap/__tests__/kompozicija.stand-in.sh /tmp/dev-harness-verify/impl118-probe-${{ github.run_id }}-${{ github.run_attempt }}

set -euo pipefail
git -C .harness118 fetch --tags origin
git -C .harness118 rev-parse --quiet --verify refs/tags/frozen/contracts/117/3 >/dev/null || {
  echo "MIGRATION_117_V1_ABSENT: pilot-app.tsx нельзя править без frozen/contracts/117/3" >&2
  exit 1
}

